INSERT INTO objects VALUES('e1-6gfrxxzxao4mbjyklc7vgcf5tcc5q5dblqgiywwu7oy3imuhmvya','element',CAST('{"children":true,"doc":"A page the way a core://Workspace looks: the title in the headline style (with Back when the page was pushed) pinned above its content, which scrolls, then a little space. With title_scrolls the title scrolls away with the content; with fills_screen the one child fills the page and there is no title. Drawn inline in another layout, only the content shows. Copy it to make your own page chrome.","examples":[{"args":{"title":"Recipes"},"children":[{"style":"Body","type":"core://Text","value_expr":"Soup"}],"note":"a pinned title"},{"args":{"title":"Feed","title_scrolls":true},"children":[{"style":"Body","type":"core://Text","value_expr":"Post"}],"note":"a title that scrolls away"}],"kind":"element","needs":{"data":[],"endpoints":[],"feeds":[],"jacks":[],"params":["fills_screen","title","title_scrolls"],"sources":[]},"node":{"arg":"fills_screen","else":{"arg":"title_scrolls","else":{"children":[{"content":{"children":[{"content":{"content_description":"Back","icon":"arrow_back","on_click":{"intent":"action.navigation.back"},"tag":"layout-back","type":"core://IconButton"},"type":"core://Conditional","value":"${local://nav#pushed}"},{"children":[{"style":"Headline","type":"core://Text","value_expr":"$arg.title"}],"padding_h_dp":16,"padding_v_dp":12,"type":"core://Column"}],"type":"core://Row"},"equals":"false","type":"core://Conditional","value":"${local://nav#inline}"},{"content":{"children":[{"type":"core://Children"},{"content":{"size_dp":16,"type":"core://Spacer"},"equals":"false","type":"core://Conditional","value":"${local://nav#inline}"}],"type":"core://Column"},"type":"core://Scroll"}],"type":"core://Column"},"then":{"content":{"children":[{"content":{"children":[{"content":{"content_description":"Back","icon":"arrow_back","on_click":{"intent":"action.navigation.back"},"tag":"layout-back","type":"core://IconButton"},"type":"core://Conditional","value":"${local://nav#pushed}"},{"children":[{"style":"Headline","type":"core://Text","value_expr":"$arg.title"}],"padding_h_dp":16,"padding_v_dp":12,"type":"core://Column"}],"type":"core://Row"},"equals":"false","type":"core://Conditional","value":"${local://nav#inline}"},{"type":"core://Children"},{"content":{"size_dp":16,"type":"core://Spacer"},"equals":"false","type":"core://Conditional","value":"${local://nav#inline}"}],"type":"core://Column"},"type":"core://Scroll"},"type":"core://IfArg"},"then":{"children":[{"content":{"content_description":"Back","icon":"arrow_back","on_click":{"intent":"action.navigation.back"},"tag":"layout-back","type":"core://IconButton"},"type":"core://Conditional","value":"${local://nav#pushed}"},{"at":0,"type":"core://Children"}],"type":"core://Column"},"type":"core://IfArg"},"params":[{"doc":"The page title.","name":"title","required":true,"type":"text"},{"default":false,"doc":"The title scrolls with the content.","name":"title_scrolls","type":"bool"},{"default":false,"doc":"The one child fills the page: no title, no scrolling.","name":"fills_screen","type":"bool"}]}' AS BLOB),'legacy_nodes,local_data,nav_data',3018);
