INSERT INTO objects VALUES('e1-ggrnz6lsn3nxvumqygoatg455ketrlwthr5uv4jfhm4va3ynh7oa','element',CAST('{"children":false,"doc":"Pixelfed''s sign-in: a sentence naming the server, a ''Sign in with Pixelfed'' button for it, and, when other servers are allowed, a server box with its own button. The pod serves it as the Pixelfed blueprint''s signed-out screen; a layout can use it too (the buttons start the pod''s Pixelfed sign-in, action.auth.login).","examples":[{"args":{"instance_url":"https://pixelfed.social","server":"pixelfed.social"},"note":"One server: the sentence and its button."},{"args":{"instance_url":"https://pixelfed.social","other_servers":true,"placeholder":"Server, e.g. pixelfed.example","server":"pixelfed.social"},"note":"Other servers allowed: the server box and its button too."}],"kind":"element","needs":{"data":[],"endpoints":[],"feeds":[],"jacks":[],"params":["instance_url","other_servers","placeholder","server"],"sources":[]},"node":{"children":[{"style":"Body","type":"core://Text","value_expr":"Sign in to $arg.server to see your home feed. Your Pixelfed token stays on your pod."},{"label":"Sign in with Pixelfed","on_click":{"app_path":"/v1/auth/pixelfed/app","instance_url":"$arg.instance_url","intent":"action.auth.login","token_path":"/v1/auth/pixelfed/token"},"type":"core://Button"},{"arg":"other_servers","then":{"children":[{"style":"Body","type":"core://Text","value_expr":"Or sign in to another Pixelfed server:"},{"field":"instance","max_length":253,"placeholder":"$arg.placeholder","type":"core://TextField"},{"label":"Sign in to this server","on_click":{"app_path":"/v1/auth/pixelfed/app","instance_url":"$form.instance","intent":"action.auth.login","token_path":"/v1/auth/pixelfed/token"},"type":"core://Button"}],"type":"core://Fragment"},"type":"core://IfArg"}],"orientation":"Vertical","padding_dp":16,"type":"core://Container"},"params":[{"doc":"The server the sentence names, e.g. pixelfed.social.","name":"server","required":true,"type":"text"},{"doc":"The server ''Sign in with Pixelfed'' signs in to, e.g. https://pixelfed.social.","name":"instance_url","required":true,"type":"uri"},{"default":false,"doc":"Offer a box to sign in to another server (local:providers#custom_server says whether the pod allows it).","name":"other_servers","type":"bool"},{"default":"Server, e.g. pixelfed.social","doc":"The server box''s placeholder.","name":"placeholder","type":"text"}]}' AS BLOB),'auth_login,button,container,legacy_nodes,text',2317);
